mapper.select:
SELECT count(*) FILTER (WHERE wi.common_status = 'IN_PROGRESS') AS in_progress, count(*) FILTER (WHERE wi.due_date = CURRENT_DATE AND wi.common_status NOT IN ('DONE', 'HOLD')) AS due_today, count(*) FILTER (WHERE wi.due_date >= CURRENT_DATE AND wi.due_date < CURRENT_DATE + INTERVAL '7 day' AND wi.common_status NOT IN ('DONE', 'HOLD')) AS due_this_week, count(*) FILTER (WHERE wi.assignee_id IS NULL AND wi.common_status <> 'DONE') AS unassigned, count(*) FILTER (WHERE wi.status_changed_at < now() - (#{staleDays} || ' day')::interval AND wi.common_status NOT IN ('DONE', 'HOLD')) AS stale FROM work_items wi WHERE wi.deleted_at IS NULL
AND 1 = 0
AND wi.project_id IN
#{pid}
AND wi.project_id = #{projectId}
